export const README_MARKER =
  '<!-- generated by skilllane-monitoring errors init -->'

/** README written next to the catalog by `errors init` (Thai, for the app's team). */
export function renderReadme(o: {
  catalogFile: string
  isDefaultPath: boolean
}): string {
  const file = o.catalogFile
  const pathSetup = o.isDefaultPath
    ? 'ไฟล์อยู่ที่ตำแหน่งมาตรฐาน SDK หาเจอเอง ไม่ต้องตั้งค่าอะไร'
    : `ไฟล์อยู่นอกตำแหน่งมาตรฐาน ต้องใส่ใน \`.env\` ของแอป:\n\n\`\`\`sh\nSKILLLANE_MONITORING_ERRORS_FILE_PATH=${file}\n\`\`\``
  return `${README_MARKER}
# ตาราง error ของแอปสำหรับ skilllane-monitoring

\`${file}\` บอก skilllane-monitoring ว่า error code ของแอปนี้แต่ละตัวคืออะไร hint และคำอธิบายจะขึ้นใน log และหน้า monitor
SDK อ่านไฟล์นี้เองตอนแอป start (ไม่ต้องลงทะเบียนหรือ import) และดูที่นี่ก่อนตารางในตัว package
ไฟล์ไม่ import อะไรจาก SDK แต่โค้ดของแอป import \`AppErrorCode\` จากไฟล์นี้ได้ (path สัมพัทธ์จากไฟล์ที่ import): \`import { AppErrorCode } from './skilllane-monitoring/errors'\`

## วิธีใช้

1. เติม \`hint\` / \`detail\` / \`howToFix\` ให้ code ใน \`${file}\` (รายการที่ \`hint\` ว่างถูกข้าม ใช้งานได้ทันทีแม้ยังเติมไม่ครบ)
2. โค้ดเดิมไม่ต้องแก้: error ที่มี code ตรงกับตารางได้ hint อัตโนมัติ
   \`\`\`ts
   throw new OrderAlreadyPaidException()                     // errorCode = 'ORDER_ALREADY_PAID'
   this.logger.error('Import failed', { code: 'E1001' })     // บันทึกโดยไม่ throw
   \`\`\`
   ใช้ code เป็นค่าคงที่ได้: \`throw new AppError(AppErrorCode.ORDER_ALREADY_PAID, 'Order already paid', { status: 409 })\`
   หรือ \`this.logger.warn('Pay failed', { code: AppErrorCode.ORDER_ALREADY_PAID, howToFix: '…' })\`
   หรือใช้ exception ของ Nest ตามเดิม แล้วใส่ช่องที่อยากทับเป็น argument ตัวที่สอง (ได้ log 1 บรรทัด body ที่ client ได้ไม่เปลี่ยน):
   \`throw new BadRequestException('Order already paid', { code: AppErrorCode.ORDER_ALREADY_PAID, howToFix: '…' })\`
3. code อยู่ช่องอื่นของ error (หรือเป็นตัวเลข) ให้เปิด \`codeOf\` ในไฟล์ เช่น \`codeOf: (err) => err.errorCode\`
4. error ที่ไม่มี code (เช่น \`throw new NotFoundException('User not found')\`) ใช้ \`messageMatch: /^User not found$/\`
   แล้ว \`error.code\` ของบรรทัดนั้นจะเป็นชื่อ key แทน \`HTTP_404\`
5. \`log.ts\` ในโฟลเดอร์นี้ให้ \`log\` ที่ไม่ต้องประกาศ \`new Logger(Class.name)\` ชื่อ class ที่เรียกขึ้นใน \`log.logger\` เอง
   \`\`\`ts
   import { log } from '../skilllane-monitoring/log'                       // import จากไฟล์นี้ ไม่ใช่จาก package
   log.error('Evaluate the exam failed', err)
   log.warn('Pay failed', { code: AppErrorCode.ORDER_ALREADY_PAID })
   \`\`\`
6. ตรวจก่อน deploy (ใช้ใน CI ได้): \`pnpm skilllane-monitoring errors check\`

## กฎ และผลเมื่อใส่ผิด

| ช่อง | กฎ | ใส่ผิดแล้ว |
|---|---|---|
| \`hint\` | ≤ 30 ตัวอักษร (≤ 40 เมื่อมี \`dependency\`) ภาษาอังกฤษ คงที่ (ใช้จัดกลุ่ม error ห้ามใส่ค่าที่เปลี่ยน) | ว่าง = ข้ามรายการ · ยาวเกิน = ตัดแล้วต่อ \`…\` |
| \`detail\` | ≤ 200 ตัวอักษร เกิดอะไรขึ้น (สาเหตุที่น่าจะเป็น) | ยาวเกิน = ตัดแล้วต่อ \`…\` |
| \`howToFix\` | ≤ 200 ตัวอักษร ต้องทำอะไร | ยาวเกิน = ตัดแล้วต่อ \`…\` |
| \`category\` | \`bug\` \`input\` \`data\` \`dependency\` \`config\` (ใครต้องแก้) | ค่าอื่น = ไม่ใช้ช่องนี้ |
| \`level\` | \`warn\` (ความผิดฝั่งผู้เรียก) หรือ \`error\` · ไม่ใส่: error ที่แอปตอบ 4xx (\`AppError\` \`status\`, exception ของ Nest) เป็น warn · request ที่ตอบ 5xx เป็น error เสมอ | ค่าอื่น = ไม่ใช้ช่องนี้ |
| \`dependency\` | \`redis\` \`oracle\` \`kafka\` \`rabbitmq\` \`smtp\` \`http\` \`s3\` \`google\` | ค่าอื่น = ไม่ใช้ช่องนี้ |
| \`messageMatch\` | RegExp | ไม่ใช่ RegExp = ไม่ใช้ช่องนี้ |
| key | \`[A-Z0-9_.-]+\` | ใช้ได้ แค่เตือนใน \`errors check\` |
| ทุกช่อง | ห้ามใส่ข้อมูลส่วนบุคคล | ตรวจอัตโนมัติไม่ได้ |

ใส่ผิดกฎแล้วแอป**ไม่ล้ม** ตอน start จะมี warn 1 บรรทัดบอกว่าปรับอะไรไป
key ที่ตรงกับตารางในตัว (เช่น \`ORA-00001\`) ทับได้: ใส่แค่ \`hint\` ส่วนที่เหลือ (\`detail\`, \`howToFix\`, category, level และคำอธิบายเฉพาะกรณี) ยังมาจากตารางในตัว

## ใช้ path อื่น หรือไฟล์ที่สร้างเอง

${pathSetup}

จะย้ายไฟล์ไปที่อื่น หรือใช้ไฟล์ที่เขียนเอง: วางไว้ใต้ \`src/\` (ให้ compile ไปกับแอป) แล้วชี้ด้วย \`SKILLLANE_MONITORING_ERRORS_FILE_PATH\`
- ใส่ path ของไฟล์ต้นฉบับได้เลย เช่น \`SKILLLANE_MONITORING_ERRORS_FILE_PATH=src/common/config/monitoring-errors.ts\` SDK แปลงเป็นไฟล์ที่ build แล้วให้ (ลอง \`dist/…\` และ \`dist/src/…\` แล้วจึงไฟล์ \`.ts\` เอง สำหรับ ts-node / tsx)
- path สัมพัทธ์นับจากโฟลเดอร์ของแอป (ที่มี \`package.json\`) ใช้ได้แม้สั่งรันจาก root ของ monorepo
- หรือใส่ path ของไฟล์ \`.js\` ที่ build แล้วตรง ๆ เช่น \`SKILLLANE_MONITORING_ERRORS_FILE_PATH=/app/dist/common/config/monitoring-errors.js\`
- ไฟล์ต้อง \`export default { errors: { codeOf?, catalog } }\` แบบไฟล์นี้

ตอน start มีบรรทัดบอกเสมอว่าใช้ไฟล์ไหน:

\`\`\`
custom error catalog: 26 codes from src/common/config/monitoring-errors.ts (/app/dist/common/config/monitoring-errors.js)
custom error catalog: not found
custom error catalog: failed to load <path>                  (reason บอกเหตุผล ใช้ตารางในตัวต่อ)
custom error catalog: N entries adjusted                    (ใส่ผิดกฎ reason บอกรายการ)
custom error catalog: more than one file found; the first is used
\`\`\`

## ข้อจำกัด

- ไฟล์ต้อง build เป็น CommonJS (ค่าปกติของ NestJS) ไฟล์แบบ ES module โหลดไม่ได้ ตอน start จะขึ้น \`failed to load\`
- \`outDir\` ของ tsconfig ที่ไม่ใช่ \`dist\` ให้ตั้ง \`SKILLLANE_MONITORING_ERRORS_FILE_PATH\` เป็น path ของไฟล์ \`.js\` ที่ build แล้ว
- ไฟล์ต้องอยู่ใต้ \`src/\` และอยู่ใน \`include\` ของ tsconfig ไม่อย่างนั้นไม่มีไฟล์ \`.js\` ให้โหลด
- คำอธิบายเฉพาะกรณี (เช่น \`ProductEntity.name got 312 (max 255)\`) มาจากตารางในตัวเท่านั้น ตารางนี้กำหนดได้แค่ข้อความคงที่
- โหลดครั้งเดียวตอน start แก้ไฟล์แล้วต้อง build และ restart แอป

## ถอดออก

\`\`\`sh
pnpm skilllane-monitoring uninstall
\`\`\`
ลบไฟล์ตาราง, README นี้ และบรรทัด \`import 'skilllane-monitoring/register'\` เขียน \`log.ts\` ใหม่เป็น \`new Logger()\` ของ Nest (โค้ดที่ import ยัง build ผ่าน) แล้วถอด package ให้ ถามยืนยันก่อนทุกครั้ง
ถ้าถอดด้วย \`pnpm remove skilllane-monitoring\` ตรง ๆ build จะพัง เพราะ \`errors.ts\` และ \`log.ts\` import จาก SDK ต้องลบ \`errors.ts\` และแก้ \`log.ts\` เอง
`
}
